with src as (select *, discount - amount as discount_minus_amount from orders where amount > 1330), StatusSummary as (select status, sum(case when status = 'RETURNED' then discount_minus_amount else 0 end) as returned_discount_minus_amount, concat_ws(', ', sort_array(collect_set(channel))) as channel_values from src group by status) select * from StatusSummary order by status desc, 3 limit 20;
